	'messages:interwiki_url_intro' => 'en:Template for URLs. The placeholder $1 will be replaced by the <em>pagename</em> in <code>[<nowiki />[prefix:<em>pagename</em>]]</code>.',
	'messages:interwiki-api-label' => 'en:API:',
	'messages:interwiki_local_0_intro' => 'en:External HTTP requests to the local wiki using this interwiki prefix in the URL will result in a "{{int:badtitle}}" error page.',
	'messages:interwiki_local_1_intro' => 'en:External HTTP requests to the local wiki using this interwiki prefix will be redirected to the target URL of the interwiki (i.e. treated like links to local pages).',
	'messages:interwiki_trans_1_intro' => 'en:If wikitext syntax <code>{<nowiki />{prefix:<em>pagename</em>}}</code> is used, allow template/page transclusion from the foreign wiki if interwiki transclusions are enabled in general ([https://www.mediawiki.org/wiki/Special:MyLanguage/Manual:$wgEnableScaryTranscluding scary transclusion]).',
	'messages:interwiki_trans_0_intro' => 'en:Do not allow <code>{<nowiki />{prefix:<em>pagename</em>}}</code> to transclude foreign templates/pages, rather look for a local page in the template namespace.',
	'messages:interwiki-cached' => 'en:The interwiki data is cached. Modifying the cache is not possible.',
	'messages:interwiki-defaulturl' => 'en:http://www.example.com/$1',
	'messages:interwiki-cannotaddlocallanguage' => 'en:Prefix "$1" matches a known language code. Adding local interlanguage prefixes is disabled when using a global interlanguage database.',
	'messages:logentry-interwiki-iw_add' => 'en:$1 {{GENDER:$2|added}} prefix "$4" ($5) (trans: $6; local: $7) to the interwiki table',
	'messages:logentry-interwiki-iw_edit' => 'en:$1 {{GENDER:$2|modified}} prefix "$4" ($5) (trans: $6; local: $7) in the interwiki table',
	'messages:logentry-interwiki-interwiki' => 'en:',
	'messages:interwiki-global-description' => 'en:These prefixes are inherited from a global configuration, and can only be edited on the source wiki.',
	'messages:interwiki-local-description' => 'en:These prefixes exist locally. Any duplicates with the global configuration will override the global definition.',
	'messages:interwiki-description' => 'en:',
	'messages:interwiki-global-language-description' => 'en:These prefixes match defined language codes, and will be used to create the "{{int:otherlanguages}}" listing when added to a page. As they are inherited from a global configuration, they can only be edited on the source wiki. Global interlanguage definitions cannot be overridden locally.',
